'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import { api } from '@/lib/api';
import { LogIn, Users, Shield, Building2, Loader2 } from 'lucide-react';
import Link from 'next/link';

interface AvailableUser {
    id: string;
    email: string;
    name: string;
    role: string;
    tenant_id: string | null;
    mock_token: string | null;
    is_active: boolean;
}

const ROLE_COLORS: Record<string, string> = {
    super_admin: '#7c3aed',
    admin: '#2563eb',
    hod: '#0891b2',
    faculty: '#059669',
    student: '#d97706',
};

const ROLE_LABELS: Record<string, string> = {
    super_admin: 'Super Admin',
    admin: 'Institution Admin',
    hod: 'Head of Department',
    faculty: 'Faculty',
    student: 'Student',
};

export default function LoginPage() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [availableUsers, setAvailableUsers] = useState<AvailableUser[]>([]);
    const [loadingUsers, setLoadingUsers] = useState(true);
    const { loginWithToken } = useAuth();
    const router = useRouter();

    useEffect(() => {
        loadAvailableUsers();
    }, []);

    const loadAvailableUsers = async () => {
        try {
            const res = await api.get<AvailableUser[]>('/api/auth/available-users');
            if (res.success) setAvailableUsers(res.data);
        } catch {
            // Backend not running or DB not connected — show empty
        }
        setLoadingUsers(false);
    };

    const handleQuickLogin = async (user: AvailableUser) => {
        if (!user.mock_token) return;
        setLoading(true);
        setError('');
        try {
            const res = await api.post<{ token: string; user: any }>('/api/auth/login', {
                email: user.email,
                password: 'mock',
            });
            if (res.success) {
                loginWithToken(res.data.token, res.data.user);
                router.push('/dashboard');
            }
        } catch (err: any) {
            setError(err.message || 'Login failed');
        }
        setLoading(false);
    };

    const handleFormLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        try {
            const res = await api.post<{ token: string; user: any }>('/api/auth/login', {
                email,
                password,
            });
            if (res.success) {
                loginWithToken(res.data.token, res.data.user);
                router.push('/dashboard');
            }
        } catch (err: any) {
            setError(err.message || 'Login failed. Only registered institutional users can sign in.');
        }
        setLoading(false);
    };

    return (
        <div style={{
            minHeight: '100vh',
            background: 'linear-gradient(135deg, #142B34 0%, #1F3F4A 50%, #142B34 100%)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: 24, position: 'relative', overflow: 'hidden',
        }}>
            {/* Dot pattern */}
            <div style={{
                position: 'absolute', inset: 0, opacity: 0.03,
                backgroundImage: 'radial-gradient(circle, white 1px, transparent 1px)',
                backgroundSize: '30px 30px',
            }} />

            <div style={{
                width: '100%', maxWidth: 1000,
                display: 'grid', gridTemplateColumns: '1fr 1fr',
                borderRadius: 16, overflow: 'hidden',
                boxShadow: '0 25px 80px rgba(0,0,0,0.3)',
                position: 'relative',
            }}>
                {/* Left — Branding */}
                <div style={{
                    background: 'linear-gradient(180deg, #142B34, #0d1f26)',
                    padding: 48, display: 'flex', flexDirection: 'column',
                    justifyContent: 'center', color: 'white',
                }}>
                    <Link href="/" style={{ textDecoration: 'none', color: 'white' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 40 }}>
                            <div style={{
                                width: 40, height: 40, borderRadius: 10,
                                background: 'rgba(255,255,255,0.1)', display: 'flex',
                                alignItems: 'center', justifyContent: 'center',
                                fontWeight: 800, fontSize: 20, fontFamily: 'Poppins',
                            }}>E</div>
                            <span style={{ fontSize: 24, fontWeight: 700, fontFamily: 'Poppins' }}>EduNexis</span>
                        </div>
                    </Link>

                    <h2 style={{ fontSize: 28, fontWeight: 700, fontFamily: 'Poppins', marginBottom: 16, lineHeight: 1.3 }}>
                        The Compliance-First Academic Operating System
                    </h2>
                    <p style={{ fontSize: 15, opacity: 0.7, lineHeight: 1.7, marginBottom: 40 }}>
                        Only users registered by your Institution Admin can sign in.
                        Secure, tenant-isolated, role-based access.
                    </p>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
                        {[
                            { icon: <Shield size={16} />, text: 'Multi-tenant data isolation' },
                            { icon: <Building2 size={16} />, text: 'Institution-managed user access' },
                            { icon: <Users size={16} />, text: 'Role-based dashboards' },
                        ].map((item, i) => (
                            <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 14, opacity: 0.8 }}>
                                <span style={{ color: '#16A34A' }}>{item.icon}</span>
                                {item.text}
                            </div>
                        ))}
                    </div>
                </div>

                {/* Right — Login */}
                <div style={{
                    background: 'white', padding: 48,
                    display: 'flex', flexDirection: 'column', justifyContent: 'center',
                }}>
                    <h3 style={{ fontSize: 22, fontWeight: 700, color: '#142B34', marginBottom: 8, fontFamily: 'Poppins' }}>
                        Sign In
                    </h3>
                    <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>
                        {availableUsers.length > 0 ? 'Select a registered user or enter credentials' : 'Enter your institutional credentials'}
                    </p>

                    {/* Available Users from DB */}
                    {loadingUsers ? (
                        <div style={{ textAlign: 'center', padding: 20, color: '#8a9aa2' }}>
                            <Loader2 size={20} style={{ animation: 'spin 1s linear infinite', margin: '0 auto 8px' }} />
                            <p style={{ fontSize: 13 }}>Loading registered users...</p>
                        </div>
                    ) : availableUsers.length > 0 && (
                        <div style={{
                            marginBottom: 24, maxHeight: 250, overflowY: 'auto',
                            display: 'flex', flexDirection: 'column', gap: 8,
                            paddingRight: 4,
                        }}>
                            <div style={{
                                fontSize: 11, fontWeight: 700, color: '#A6A9AC',
                                textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4,
                                display: 'flex', alignItems: 'center', gap: 6,
                            }}>
                                <Users size={12} /> Registered Users ({availableUsers.length})
                            </div>
                            {availableUsers.map((u) => (
                                <button
                                    key={u.id || u.email}
                                    onClick={() => handleQuickLogin(u)}
                                    disabled={loading}
                                    style={{
                                        display: 'flex', alignItems: 'center', gap: 12,
                                        padding: '10px 14px', borderRadius: 8,
                                        border: '1px solid #e2e6ea', background: '#fafbfc',
                                        cursor: 'pointer', width: '100%', textAlign: 'left',
                                        transition: 'all 0.2s', opacity: loading ? 0.5 : 1,
                                    }}
                                    onMouseEnter={(e) => {
                                        e.currentTarget.style.borderColor = ROLE_COLORS[u.role] || '#142B34';
                                        e.currentTarget.style.background = '#f0f4f7';
                                    }}
                                    onMouseLeave={(e) => {
                                        e.currentTarget.style.borderColor = '#e2e6ea';
                                        e.currentTarget.style.background = '#fafbfc';
                                    }}
                                >
                                    <div style={{
                                        width: 36, height: 36, borderRadius: 8,
                                        background: ROLE_COLORS[u.role] || '#142B34', color: 'white',
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        fontSize: 14, fontWeight: 700, flexShrink: 0,
                                    }}>
                                        {u.name.charAt(0).toUpperCase()}
                                    </div>
                                    <div style={{ flex: 1, minWidth: 0 }}>
                                        <div style={{ fontSize: 13, fontWeight: 600, color: '#142B34' }}>{u.name}</div>
                                        <div style={{ fontSize: 11, color: '#8a9aa2', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{u.email}</div>
                                    </div>
                                    <span style={{
                                        fontSize: 10, fontWeight: 700, padding: '3px 8px',
                                        borderRadius: 4, background: `${ROLE_COLORS[u.role] || '#142B34'}15`,
                                        color: ROLE_COLORS[u.role] || '#142B34', textTransform: 'uppercase',
                                        letterSpacing: 0.5, whiteSpace: 'nowrap',
                                    }}>
                                        {ROLE_LABELS[u.role] || u.role}
                                    </span>
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Divider */}
                    {availableUsers.length > 0 && (
                        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20 }}>
                            <div style={{ flex: 1, height: 1, background: '#e2e6ea' }} />
                            <span style={{ fontSize: 12, color: '#A6A9AC', fontWeight: 500 }}>OR</span>
                            <div style={{ flex: 1, height: 1, background: '#e2e6ea' }} />
                        </div>
                    )}

                    {/* Form */}
                    <form onSubmit={handleFormLogin}>
                        <div className="form-group">
                            <label>Email</label>
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                placeholder="admin@institution.edu"
                                required
                            />
                        </div>
                        <div className="form-group">
                            <label>Password</label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                placeholder="••••••••"
                            />
                        </div>
                        {error && (
                            <div style={{
                                background: '#fee2e2', border: '1px solid #fecaca', borderRadius: 8,
                                padding: '10px 14px', marginBottom: 12, color: '#991b1b', fontSize: 13,
                            }}>
                                {error}
                            </div>
                        )}
                        <button type="submit" className="btn-primary" style={{ width: '100%', justifyContent: 'center' }} disabled={loading}>
                            {loading ? (
                                <><Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} /> Signing in...</>
                            ) : (
                                <><LogIn size={16} /> Sign In</>
                            )}
                        </button>
                    </form>

                    <p style={{ fontSize: 12, color: '#A6A9AC', marginTop: 16, textAlign: 'center' }}>
                        Don&apos;t have an account? Contact your Institution Admin.
                    </p>
                </div>
            </div>
        </div>
    );
}
